// External identifiers are decoded separately from confirmed label ingredients.
(()=>{
const codeSource='https://www.fao.org/gsfaonline/additives/index.html';
const mfds='https://www.foodsafetykorea.go.kr/foodcode/pdf/2/2-5.pdf';
const catalog={
 e327:{name:'젖산칼슘',english:'Calcium lactate',roles:['nutrition','acidity'],description:'칼슘을 보충하거나 식품의 산도를 조절하는 용도로 쓰여요.',source:mfds},
 e330:{name:'구연산',english:'Citric acid',roles:['acidity'],description:'식품의 산성·알칼리성 정도를 조절할 때 쓰여요.',source:mfds},
 e575:{name:'글루코노델타락톤',english:'Glucono delta-lactone',roles:['acidity'],description:'식품의 산도를 조절하는 데 쓰일 수 있어요. GDL이라고도 불러요.',source:'https://www.fao.org/gsfaonline/additives/details.html?id=172'},
 e621:{name:'L-글루탐산나트륨',english:'Monosodium L-glutamate',nickname:'MSG',roles:['flavour'],description:'음식의 감칠맛을 더하는 데 쓰이는 성분이에요.',source:mfds}
};
const roles={nutrition:{label:'영양 보충용',path:'M12 3v18M3 12h18',hint:'영양성분을 더해요'},acidity:{label:'산도 조절용',path:'M12 3s-7 8-7 12a7 7 0 0 0 14 0c0-4-7-12-7-12z',hint:'산성·알칼리성을 조절해요'},flavour:{label:'감칠맛용',path:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z',hint:'맛을 더해요'}};
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function code(raw){const v=String(raw).trim().toLowerCase().replace(/^[a-z]{2}:/,'');return /^e\d{3,4}(?:[a-z]|i{1,3}|iv|v)?$/.test(v)?v:null}
function decode(raw){const key=code(raw);return {key:key||String(raw),code:key?key.toUpperCase():'미확인 코드',raw:String(raw),...(catalog[key]||{name:'이름 확인 중',roles:[],description:'아직 설명이 등록되지 않은 코드예요. 원본 자료와 포장지에서 이름을 확인해 주세요.'}),known:!!catalog[key]}}
function list(raw){const map=new Map();for(const v of raw||[]){if(typeof v!=='string')continue;const d=decode(v);if(!map.has(d.key))map.set(d.key,d)}return [...map.values()]}
const icon=role=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${roles[role]?.path||'M12 7v6M12 17h.01'}"/></svg>`;
function cards(raw){const items=list(raw),known=items.filter(e=>e.known).length,summary=Object.keys(roles).filter(r=>items.some(e=>e.roles.includes(r)));return `<section class="decoded-section" aria-label="첨가물 한글 이름과 용도"><div class="decoded-heading"><div><span class="eyebrow small">쉽게 읽는 성분</span><h4>이 첨가물은 어떤 일을 할까요?</h4></div><span class="decoded-total">외부 자료 ${items.length}종</span></div>${items.length?`<div class="decoded-role-summary">${summary.map(r=>`<span class="decoded-role role-${r}">${icon(r)}${roles[r].label}</span>`).join('')}</div><div class="decoded-grid">${items.map(e=>`<article class="decoded-card ${e.known?'':'decoded-pending'}"><div class="decoded-card-top"><span class="decoded-icon role-${e.roles[0]||'unknown'}">${icon(e.roles[0])}</span><small>${esc(e.code)}</small></div><h5>${esc(e.name)}${e.nickname?` <span class="decoded-nickname">${e.nickname}</span>`:''}</h5><div class="decoded-tags">${e.roles.map(r=>`<span class="decoded-role role-${r}">${roles[r].label}</span>`).join('')||'<span class="decoded-role role-unknown">설명 준비 중</span>'}</div><p>${esc(e.description)}</p><details><summary>이름·설명 근거 보기</summary><small>${esc(e.english||e.raw)}</small>${e.known?`<a href="${codeSource}" target="_blank" rel="noopener noreferrer">국제번호·성분명 · Codex ↗</a><a href="${e.source}" target="_blank" rel="noopener noreferrer">대표 용도·설명 근거 ↗</a><small>자료 대조 2026.11.06</small>`:''}</details></article>`).join('')}</div><p class="decoded-context">${known}종의 이름을 연결했어요.${known<items.length?` ${items.length-known}종은 추가 확인이 필요해요.`:''} 용도는 성분의 일반적인 역할이며, 이 제품의 실제 사용 목적·함량은 확인되지 않았어요.</p>`:'<div class="decoded-missing"><strong>첨가물 자료가 등록되어 있지 않아요</strong><p>자료가 없다는 뜻이며, 무첨가로 확인된 것은 아니에요. 포장지 원재료 표시를 함께 확인해 주세요.</p></div>'}</section>`}
const allergens={'milk':'우유','eggs':'알류','peanuts':'땅콩','soybeans':'대두','nuts':'견과류','fish':'생선','crustaceans':'갑각류','molluscs':'연체동물','celery':'셀러리','mustard':'겨자','sesame-seeds':'참깨','lupin':'루핀콩','sulphur-dioxide-and-sulphites':'이산화황·아황산류','gluten':'글루텐 함유 곡물'};
function allergenPanel(raw){const names=[...new Set((raw||[]).filter(v=>typeof v==='string').map(v=>allergens[v.toLowerCase().replace(/^[a-z]{2}:/,'')]||'이름 확인 필요'))];return `<section class="decoded-allergens"><span class="decoded-allergen-icon" aria-hidden="true">ⓘ</span><div><h4>알레르기 표시</h4>${names.length?`<div class="decoded-tags">${names.map(n=>`<span class="allergen-tag">${esc(n)}</span>`).join('')}</div><p>외부 자료에 등록된 항목이에요. 포장지의 알레르기·혼입 가능성 표시를 확인해 주세요.</p>`:'<strong>자료 미제공</strong><p>알레르기 성분이 없다는 뜻은 아니에요. 포장지에서 확인해 주세요.</p>'}</div></section>`}
window.AdditiveCodes={decode,list,cards,allergenPanel};
})();
